create table if not exists public.admin_content_drafts (id uuid primary key default gen_random_uuid(),draft_type text not null check(draft_type in ('announcement','event','roleplay','newspaper','policy','school_state','other')),title text not null,content jsonb not null default '{}'::jsonb,status text not null default 'draft' check(status in ('draft','ready','published','archived')),scheduled_for timestamptz,created_by uuid not null default auth.uid(),updated_by uuid not null default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists admin_content_drafts_status_idx on public.admin_content_drafts(status,scheduled_for);alter table public.admin_content_drafts enable row level security;create policy admin_content_drafts_manage on public.admin_content_drafts for all using(public.school_staff_can_manage()) with check(public.school_staff_can_manage());
create table if not exists public.owner_watchlist (id uuid primary key default gen_random_uuid(),item_type text not null check(item_type in ('bug','feature','event','election','moderation','roleplay','deployment','other')),title text not null,note text not null default '',reference_id text,status text not null default 'watching' check(status in ('watching','resolved','dismissed')),priority text not null default 'normal' check(priority in ('low','normal','high','urgent')),created_by uuid not null default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.owner_watchlist enable row level security;create policy owner_watchlist_manage on public.owner_watchlist for all using(public.current_owner_status()) with check(public.current_owner_status());
create table if not exists public.portal_onboarding_progress (character_id uuid primary key references public.characters(id) on delete cascade,checklist jsonb not null default '{}'::jsonb,tutorial_completed jsonb not null default '{}'::jsonb,orientation_started_at timestamptz not null default now(),orientation_completed_at timestamptz,updated_at timestamptz not null default now());alter table public.portal_onboarding_progress enable row level security;create policy onboarding_self on public.portal_onboarding_progress for all using(public.current_user_owns_character(character_id) or public.school_staff_can_manage()) with check(public.current_user_owns_character(character_id) or public.school_staff_can_manage());
create table if not exists public.portal_feature_discovery (character_id uuid not null references public.characters(id) on delete cascade,feature_key text not null,first_seen_at timestamptz not null default now(),opened_at timestamptz,dismissed_at timestamptz,primary key(character_id,feature_key));alter table public.portal_feature_discovery enable row level security;create policy feature_discovery_self on public.portal_feature_discovery for all using(public.current_user_owns_character(character_id) or public.school_staff_can_manage()) with check(public.current_user_owns_character(character_id) or public.school_staff_can_manage());
create table if not exists public.page_changelog_entries (id uuid primary key default gen_random_uuid(),page_key text not null,title text not null,summary text not null default '',version text,visibility text not null default 'all' check(visibility in ('all','student','faculty','admin','owner')),published_at timestamptz not null default now(),created_by uuid default auth.uid());create index if not exists page_changelog_entries_page_idx on public.page_changelog_entries(page_key,published_at desc);alter table public.page_changelog_entries enable row level security;create policy page_changelog_read on public.page_changelog_entries for select using(auth.uid() is not null);create policy page_changelog_staff on public.page_changelog_entries for all using(public.school_staff_can_manage()) with check(public.school_staff_can_manage());
create table if not exists public.portal_usage_events (id bigint generated always as identity primary key,character_id uuid references public.characters(id) on delete set null,portal_role text,page_key text not null,event_type text not null default 'view',metadata jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now());create index if not exists portal_usage_events_time_idx on public.portal_usage_events(occurred_at desc,page_key);alter table public.portal_usage_events enable row level security;create policy portal_usage_self_insert on public.portal_usage_events for insert with check(character_id is null or public.current_user_owns_character(character_id));create policy portal_usage_staff_read on public.portal_usage_events for select using(public.school_staff_can_manage());
create table if not exists public.portal_health_checks (id uuid primary key default gen_random_uuid(),check_key text not null,check_type text not null,summary text not null,status text not null check(status in ('healthy','warning','failed','unknown')),details jsonb not null default '{}'::jsonb,checked_at timestamptz not null default now(),resolved_at timestamptz);create index if not exists portal_health_checks_latest_idx on public.portal_health_checks(check_key,checked_at desc);alter table public.portal_health_checks enable row level security;create policy portal_health_owner_read on public.portal_health_checks for select using(public.current_owner_status() or public.school_staff_can_manage());create policy portal_health_staff_manage on public.portal_health_checks for all using(public.school_staff_can_manage()) with check(public.school_staff_can_manage());
create table if not exists public.owner_daily_change_reports (id uuid primary key default gen_random_uuid(),report_date date not null unique,summary text not null default '',changes jsonb not null default '[]'::jsonb,generated_at timestamptz not null default now(),generated_by uuid default auth.uid());alter table public.owner_daily_change_reports enable row level security;create policy owner_change_reports on public.owner_daily_change_reports for all using(public.current_owner_status()) with check(public.current_owner_status());
